<script setup lang="ts">
import { computed, ref, defineAsyncComponent } from 'vue';
import AccountLibrary from './AccountLibrary.vue';
import DefinitionLibrary from './DefinitionLibrary.vue';
import AxisCreation from './AxisCreation.vue';
import { useAccountStore } from './stores/account';
import { actorLabel, definitionLabel, recordLabel, nodeLabel, effectLabel, projectLabel, unitLabel, operationLabel, diagnosticLabel, statusLabel, inputLabel, capabilityLabel, errorLabel } from './domain/workbench-labels';

import { storeToRefs } from 'pinia';
import type { WorkbenchNode } from '@leyline/schema';
import { useAxisWorkspaceStore } from './stores/axis-workspace';
import { acceptanceCases, nextRecordId, removeProjectActor, removeTimelineRecord, setDamageSelected, type AcceptanceCase } from './domain/workbench-project';
import { getDamagePresentation, formatWorkbenchExpression } from './domain/workbench-display';
import anemoEmblem from './assets/genshin/element-anemo.webp';
import geoEmblem from './assets/genshin/element-geo.webp';

const RealGamePanel = defineAsyncComponent(() => import('./RealGamePanel.vue'));
const workspace = useAxisWorkspaceStore();
const accountStore = useAccountStore();
const { project, result, actor, actorId, selectedId, dirty, busy, notice, error } = storeToRefs(workspace);
type Page = 'characters' | 'artifacts' | 'projects' | 'team' | 'timeline' | 'analysis' | 'definitions' | 'settings';
const page = ref<Page>('timeline');
const collapsed = ref(false);
const mobileOpen = ref(false);
const layer = ref('all');
const definitionFilter = ref('all');
const newCondition = ref('');
const conditionKeys = computed(() => [...new Set([...Object.keys(project.value.conditions), ...project.value.definitions.flatMap(d => [...d.effects.flatMap(e => e.condition ? [e.condition] : []), ...d.nodes.flatMap(n => n.op === 'condition' ? [n.key] : [])])])]);
function addCondition() {
  const key = newCondition.value.trim();
  if (!key || key.length > 160) { error.value = '请填写不超过 160 字的条件名称。'; return; }
  if (!Object.hasOwn(project.value.conditions, key)) workspace.command(draft => { draft.conditions[key] = null; });
  newCondition.value = '';
}
const fileInput = ref<HTMLInputElement>();
const isAccountPage = computed(() => page.value === 'characters' || page.value === 'artifacts');
const titles: Record<Page, string> = { characters: '角色', artifacts: '圣遗物', projects: '轴项目', team: '队伍与候选方案', timeline: '时间轴', analysis: '伤害分析', definitions: '内容定义库', settings: '设置与帮助' };
const groups: { title: string; items: { id: Page; name: string; icon: string }[] }[] = [
  { title: '账号资料', items: [{ id: 'characters', name: '角色', icon: 'person' }, { id: 'artifacts', name: '圣遗物', icon: 'diamond' }] },
  { title: '轴项目', items: [{ id: 'projects', name: '项目', icon: 'folder' }, { id: 'team', name: '队伍', icon: 'team' }, { id: 'timeline', name: '时间轴', icon: 'timeline' }, { id: 'analysis', name: '伤害分析', icon: 'chart' }] },
  { title: '内容与规则', items: [{ id: 'definitions', name: '内容定义库', icon: 'layers' }] },
];
const icons: Record<string, string> = {
  person: 'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M20 8v6 M17 11h6',
  diamond: 'M12 3 21 12 12 21 3 12 12 3 M8 8l8 8 M16 8l-8 8',
  folder: 'M3 7V5h6l2 2h10v13H3V7Z',
  team: 'M3 20v-2a4 4 0 0 1 4-4h3a4 4 0 0 1 4 4v2 M8.5 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M16 4a4 4 0 0 1 0 7 M18 14a4 4 0 0 1 3 4v2',
  timeline: 'M3 6h18 M3 12h18 M3 18h18 M7 3v6 M16 9v6 M10 15v6',
  chart: 'M4 3v18h17 M9 17v-5 M14 17V7 M19 17v-8',
  layers: 'm12 3 10 5-10 5L2 8 12 3 M2 12l10 5 10-5 M2 16l10 5 10-5',
};
const visibleDefinitions = computed(() => project.value.definitions.filter(d => definitionFilter.value === 'all' || d.source.kind === definitionFilter.value));
const sortedRecords = computed(() => [...project.value.timeline].sort((a, b) => a.timeMs - b.timeMs || a.order - b.order || a.id.localeCompare(b.id)));
const damageRecords = computed(() => sortedRecords.value.filter(r => r.kind === 'damage'));
const actions = computed(() => sortedRecords.value.filter(r => r.kind === 'action'));
const selected = computed(() => project.value.timeline.find(r => r.id === selectedId.value));
const selectedResult = computed(() => result.value.points.find(p => p.id === selectedId.value));
const presentation = computed(() => getDamagePresentation(project.value, selectedId.value));
const selectedTarget = computed(() => !project.value.objective.damageIds || project.value.objective.damageIds.includes(selectedId.value));
const equipmentDefinitions = computed(() => project.value.definitions.filter(d => d.id === actor.value?.character || d.id === actor.value?.weapon));
const effects = computed(() => project.value.candidate.actors.flatMap(owner => [owner.character, owner.weapon].flatMap(id => {
  const definition = project.value.definitions.find(d => d.id === id);
  return (definition?.effects ?? []).flatMap(effect => {
    const triggers = effect.action ? actions.value.filter(a => a.actor === owner.id && a.definition === effect.action) : [null];
    return triggers.map(trigger => ({ key: `${owner.id}/${id}/${effect.id}/${trigger?.id ?? 'axis'}`, owner: owner.id, definition: id,
      effect: effect.id, condition: effect.condition, startMs: (trigger?.timeMs ?? 0) + effect.startMs,
      endMs: (trigger?.timeMs ?? 0) + effect.endMs, expression: formatWorkbenchExpression(project.value, id, effect.value) }));
  });
})));
const durationMs = computed(() => Math.max(8000, ...project.value.timeline.map(r => Number.isFinite(r.timeMs) ? r.timeMs + 1000 : 0), ...effects.value.map(e => Number.isFinite(e.endMs) ? e.endMs : 0)));
const num = (value: number | null | undefined) => value === null || value === undefined || !Number.isFinite(value) ? '待确认' : value.toLocaleString('zh-CN', { maximumFractionDigits: 4 });
const realPartsLabels: Record<string,string> = {attack:'攻击力',multiplier:'技能倍率',bonus:'增伤乘区',crit:'暴击乘区',defense:'防御乘区',resistance:'抗性乘区'};
const number = (event: Event) => { const value = (event.target as HTMLInputElement).value; return value.trim() ? Number(value) : NaN; };
const text = (event: Event) => (event.target as HTMLInputElement).value;
const percent = (ms: number) => `${Number.isFinite(ms) ? Math.max(0, Math.min(100, ms / durationMs.value * 100)) : 0}%`;
function navigate(target: Page) { page.value = target; mobileOpen.value = false; }
function openPoint(id: string) { selectedId.value = id; navigate('timeline'); }
function updateTime(event: Event) { if (selected.value) selected.value.timeMs = number(event); }
function updateTarget(event: Event) { if (selected.value?.kind === 'damage') workspace.command(draft => setDamageSelected(draft, selectedId.value, (event.target as HTMLInputElement).checked)); }
function conditionState(key?: string) {
  if (!key) return '无需额外条件';
  return project.value.conditions[key] === true ? '明确满足' : project.value.conditions[key] === false ? '明确不满足' : '待确认';
}
function conditionValue(key: string) { return project.value.conditions[key] === true ? 'true' : project.value.conditions[key] === false ? 'false' : 'unknown'; }
function setCondition(key: string, event: Event) { const value = text(event); project.value.conditions[key] = value === 'unknown' ? null : value === 'true'; }
function toggleCondition(effect: { condition?: string }, event: Event) {
  workspace.command(() => {
  if ((event.target as HTMLInputElement).checked) {
    effect.condition = effect.condition ?? 'triggered';
    if (!Object.hasOwn(project.value.conditions, effect.condition)) project.value.conditions[effect.condition] = null;
  } else delete effect.condition;
  });
}
function constant(node: WorkbenchNode) { return node.op === 'constant' ? node.quantity : undefined; }
function addRecord(kind: 'action' | 'damage') {
  const owner = actor.value;
  const definition = kind === 'damage' ? project.value.definitions.find(d => owner?.realBuild ? d.id === `${owner.id}-real-damage` : d.damage) : project.value.definitions.find(d => d.id === owner?.character);
  if (!owner || !definition) return;
  const id = nextRecordId(project.value);
  workspace.command(draft => {
    draft.timeline.push({ id, kind, actor: owner.id, definition: definition.id, ...(kind === 'damage' && owner.realBuild ? { realDamage: { skillId: owner.realBuild.character.skills.find(skill => skill.support.supported)?.id ?? '', hitIndex: 0, crit: 'noncritical' as const, reaction: 'none' as const } } : {}), timeMs: 0, order: Math.max(-1, ...draft.timeline.map(r => r.order)) + 1 });
    if (kind === 'damage' && draft.objective.damageIds) draft.objective.damageIds.push(id);
  });
  selectedId.value = id;
}
function removeActor() {
  const id = actorId.value;
  workspace.command(draft => removeProjectActor(draft, id));
  actorId.value = project.value.candidate.actors[0]?.id ?? '';
  if (!project.value.timeline.some(record => record.id === selectedId.value)) selectedId.value = project.value.timeline[0]?.id ?? '';
}
function removeRecord(id: string) {
  workspace.command(draft => removeTimelineRecord(draft, id));
  if (selectedId.value === id) selectedId.value = project.value.timeline[0]?.id ?? '';
}
async function openProject() { if (!await workspace.openNativeProject()) fileInput.value?.click(); }
async function importFile(event: Event) {
  const input = event.target as HTMLInputElement;
  const file = input.files?.[0];
  if (file) await workspace.inputFile(file);
  input.value = '';
}
function loadSample(id: AcceptanceCase) { workspace.loadSample(id); navigate('timeline'); }
</script>

<template>
  <div class="workspace-design" :class="{ compact: collapsed, 'mobile-open': mobileOpen }">
    <button v-if="mobileOpen" class="drawer-shade" aria-label="关闭导航遮罩" @click="mobileOpen = false"></button>
    <nav class="design-sidebar" aria-label="工作台功能导航">
      <div class="brand"><span class="brand-symbol">地<span>·</span></span><div class="brand-copy"><strong>地脉</strong><small>轴与配装工作台</small></div><button class="collapse-button" :aria-label="collapsed ? '展开侧栏' : '折叠侧栏'" @click="collapsed = !collapsed">{{ collapsed ? '›' : '‹' }}</button></div>
      <div class="account-picker"><span class="context-label">账号资料</span><label><span class="account-avatar">◇</span><select aria-label="当前账号" disabled><option>{{ accountStore.account.name }}</option></select></label><small>账号与当前轴独立保存</small></div>
      <div class="nav-groups"><div v-for="group in groups" :key="group.title" class="nav-group"><p>{{ group.title }}</p><button v-for="item in group.items" :key="item.id" :class="{ active: page === item.id }" :aria-current="page === item.id ? 'page' : undefined" :aria-label="`导航 ${item.name}`" :data-testid="`workspace-nav-${item.id}`" :title="item.name" @click="navigate(item.id)"><svg viewBox="0 0 24 24" aria-hidden="true"><path :d="icons[item.icon]" /></svg><span>{{ item.name }}</span><span v-if="item.id === 'timeline'" class="nav-count">{{ project.timeline.length }}</span></button></div></div>
      <div class="sidebar-bottom"><button :class="{ active: page === 'settings' }" aria-label="导航 设置与帮助" @click="navigate('settings')"><span class="settings-symbol">⚙</span><span>设置与帮助</span></button><div class="sidebar-version"><img :src="anemoEmblem" alt="" width="20" height="20" class="element-emblem"><span>本地工作台 · v0.2</span></div></div>
    </nav>

    <div class="workspace-body">
      <header class="design-topbar"><div class="topbar-context"><button class="mobile-menu" aria-label="打开功能导航" @click="mobileOpen = !mobileOpen">☰</button><span class="context-label">{{ isAccountPage ? '账号资料' : page === 'definitions' ? '内容与规则' : '当前轴' }}</span><span class="breadcrumb-slash">/</span><strong>{{ isAccountPage ? '独立资料库' : projectLabel(project) }}</strong><span class="snapshot-tag">{{ dirty ? '未保存' : '已载入' }}</span></div><div class="topbar-actions"><button :disabled="!workspace.canUndo" @click="workspace.undo()">撤销</button><button :disabled="!workspace.canRedo" @click="workspace.redo()">重做</button><span class="header-objective">目标 <strong data-testid="workspace-objective">{{ num(result.objectiveValue) }}</strong></span><span class="header-objective">全轴 <strong data-testid="workspace-total">{{ num(result.totalValue) }}</strong></span><button class="secondary" :disabled="busy" @click="openProject">打开轴项目</button><button class="primary" :disabled="busy" @click="workspace.saveProject()">保存轴项目</button></div></header>
      <input ref="fileInput" type="file" accept=".json,application/json" aria-label="导入轴项目文件" class="shell-file-input" @change="importFile">
      <div class="shell-notices"><div class="shell-project-actions"><span role="status">{{ workspace.runState }}</span><button :disabled="workspace.runState !== '计算中'" @click="workspace.cancelRun()">取消计算</button><button @click="workspace.run()">重新计算</button><button :disabled="!workspace.recoveryAvailable" @click="workspace.recover()">恢复上次编辑</button></div><p v-if="notice" role="status">{{ notice }}</p><div v-if="error" role="alert" class="shell-error">{{ errorLabel(error) }}<details><summary>技术详情</summary>{{ error }}</details></div></div>
      <div class="page-heading"><div><div class="section-eyebrow">{{ isAccountPage ? '账号资料库' : page === 'definitions' ? '内容定义库' : '轴项目工作区' }}</div><h1>{{ titles[page] }}</h1><p>{{ isAccountPage ? '账号资料与轴内候选配置分别管理。' : page === 'definitions' ? '独立保存和复用内容定义；轴使用所选版本的副本。' : '队伍、时间轴和分析使用同一份轴项目；编辑后立即重新求值。' }}</p></div><div class="heading-actions"><span class="save-context">{{ result.status === 'complete' ? '已完整计算' : result.status === 'partial' ? '部分待确认' : '输入需修正' }} · {{ dirty ? '有未保存修改' : '当前无修改' }}</span></div></div>

      <div v-if="page === 'timeline' || page === 'analysis' || page === 'team'" class="project-context"><div class="project-identity"><span class="mini-avatar">轴</span><div><strong>{{ actor ? actorLabel(project, actor.id) : '尚未配置角色' }}</strong><small>项目快照 · 与账号独立</small></div></div><div class="context-divider"></div><div class="compact-stat"><span>当前候选</span><strong>{{ actor ? definitionLabel(project, actor.weapon) : '无' }}</strong></div><div class="compact-stat"><span>记录</span><strong>{{ project.timeline.length }} 条</strong></div><div class="compact-stat"><span>规则</span><strong>规则快照</strong></div><button class="text-button" @click="navigate('team')">编辑队伍与方案 →</button></div>

      <div v-if="page === 'timeline'" class="timeline-layout">
        <section class="timeline-main panel">
          <div class="panel-heading"><div><h2>动作与伤害标注</h2><p>{{ durationMs / 1000 }} 秒视图 · {{ damageRecords.length }} 个伤害点 · {{ actions.length }} 个动作</p></div><span class="subtle-tag">无视频亦可编辑</span></div>
          <div class="timeline-toolbar"><div class="segmented" aria-label="时间轴信息层"><button v-for="tab in [{ id: 'all', name: '全部图层' }, { id: 'damage', name: '伤害' }, { id: 'effects', name: '效果' }]" :key="tab.id" :class="{ selected: layer === tab.id }" @click="layer = tab.id">{{ tab.name }}</button></div><div class="timeline-tools"><button :disabled="!actor" @click="addRecord('action')">添加动作</button><button :disabled="!actor || !project.definitions.some(d => d.damage)" @click="addRecord('damage')">添加伤害点</button></div></div>
          <div class="tracks-scroller"><div class="tracks">
            <div class="ruler"><span class="track-label">记录 / 时间</span><div class="ruler-marks"><span v-for="tick in 9" :key="tick" :style="{ left: `${(tick - 1) / 8 * 100}%` }">{{ num((tick - 1) * durationMs / 8000) }}<small>秒</small></span></div></div>
            <div class="track-row action-track" :class="{ faded: layer !== 'all' }"><div class="track-label"><span class="track-dot slate"></span><strong>动作</strong><small>手动记录</small></div><div class="track-content"><div class="track-grid"></div><span v-if="!actions.length" class="empty-track">当前轴没有动作记录</span><button v-for="record in actions" :key="record.id" class="hit-marker" :style="{ left: percent(record.timeMs) }" :data-record-id="record.id" :aria-label="`选择动作 ${recordLabel(project, record.id)}`" @click="selectedId = record.id"><span class="marker-card"><small>{{ record.timeMs }}毫秒</small><strong>{{ recordLabel(project, record.id) }}</strong></span></button></div></div>
            <div class="track-row damage-track" :class="{ faded: layer === 'effects' }"><div class="track-label"><span class="track-dot green"></span><strong>伤害点</strong><small>{{ damageRecords.length }} 条标注</small></div><div class="track-content"><div class="track-grid"></div><button v-for="record in damageRecords" :key="record.id" class="hit-marker" :class="{ chosen: selectedId === record.id }" :style="{ left: percent(record.timeMs) }" :data-record-id="record.id" :aria-label="`选择伤害点 ${recordLabel(project, record.id)}`" @click="selectedId = record.id"><span class="marker-stem"></span><span class="marker-card"><small>{{ record.timeMs / 1000 }}秒 · {{ recordLabel(project, record.id) }}</small><strong>{{ num(result.points.find(p => p.id === record.id)?.value) }}</strong></span><span class="marker-diamond"></span></button></div></div>
            <div class="track-row effect-track" :class="{ faded: layer === 'damage' }"><div class="track-label"><span class="track-dot gold"></span><strong>区间效果</strong><small>候选装备推导</small></div><div class="track-content"><div class="track-grid"></div><div v-for="effect in effects" :key="effect.key" class="effect-bar" :style="{ left: percent(effect.startMs), width: percent(effect.endMs - effect.startMs) }" :title="`${actorLabel(project, effect.owner)} / ${effect.expression} / ${conditionState(effect.condition)}`"><span>{{ definitionLabel(project, effect.definition) }} · {{ effectLabel(project, effect.definition, effect.effect) }}</span><small>[{{ effect.startMs }}, {{ effect.endMs }}) · {{ conditionState(effect.condition) }}</small></div><span v-if="!effects.length" class="empty-track">当前配装没有推导出区间效果</span></div></div>
            <div class="track-row future-track"><div class="track-label"><span class="track-dot pale"></span><strong>快照 / 历史</strong><small>尚未支持</small></div><div class="track-content"><div class="track-grid"></div><span class="future-track-note">当前只支持普通伤害与基础区间效果</span></div></div>
          </div></div>
          <div class="timeline-footer"><span>整数毫秒 · 区间左闭右开</span><p>选中记录后可修改时间、同刻顺序和目标归属。</p></div>
          <div class="axis-summary"><div><small>所选目标伤害</small><strong>{{ num(result.objectiveValue) }}</strong></div><div><small>全轴总伤害</small><strong>{{ num(result.totalValue) }}</strong></div><div class="summary-state">{{ result.status === 'complete' ? '已完整计算' : '存在未确定或非法输入' }}<button class="text-button" @click="navigate('analysis')">进入伤害分析 →</button></div></div>
          <details class="shell-record-list" open><summary>记录列表（{{ sortedRecords.length }}）</summary><div v-for="record in sortedRecords" :key="record.id" class="shell-record-row"><button @click="selectedId = record.id">{{ recordLabel(project, record.id) }} · {{ record.kind === 'damage' ? '伤害' : '动作' }} · {{ record.timeMs }} 毫秒</button><button :aria-label="`删除记录 ${recordLabel(project, record.id)}`" @click="removeRecord(record.id)">移除</button></div><p v-if="!sortedRecords.length">当前轴没有记录。请先在队伍页准备角色，再添加动作与伤害点。</p></details>
        </section>
        <aside class="record-inspector panel" aria-label="所选记录详情"><template v-if="selected"><div class="inspector-title"><span class="section-eyebrow">记录详情</span><span class="subtle-tag">{{ selected.kind === 'damage' ? '伤害点' : '动作' }}</span></div><h2>{{ recordLabel(project, selected.id) }}</h2><p class="monospace muted">{{ definitionLabel(project, selected.definition) }}</p><div v-if="selected.kind === 'damage'" class="inspector-damage">{{ num(selectedResult?.value) }}<small>计算伤害</small></div><div class="inspector-fields"><label>命中时间（毫秒）<input aria-label="命中时间（毫秒）" type="number" min="0" step="1" :value="selected.timeMs" @input="updateTime"></label><label>同刻顺序<input type="number" min="0" step="1" :value="selected.order" @input="selected.order = number($event)"></label><label>归属角色<select v-model="selected.actor" aria-label="归属角色"><option v-for="owner in project.candidate.actors" :key="owner.id" :value="owner.id">{{ actorLabel(project, owner.id) }}</option></select></label><label>记录定义<select v-model="selected.definition" aria-label="记录定义"><option v-for="definition in project.definitions.filter(d => selected?.kind === 'action' || d.damage)" :key="definition.id" :value="definition.id">{{ definitionLabel(project, definition.id) }}</option></select></label><label v-if="selected.kind === 'damage'" class="checkbox-line"><input aria-label="计入当前目标" type="checkbox" :checked="selectedTarget" @change="updateTarget">计入当前目标</label></div><div v-if="selected.kind === 'damage'" class="inspector-section"><h3>基础计算关系</h3><div class="formula-box"><span>{{ presentation.definitionLabel }} / {{ presentation.rootLabel }}</span><strong>{{ presentation.expression }}</strong></div><p class="muted">实际结果同时读取当前候选条件与区间效果，不推断暴击或反应。</p></div><div v-if="selectedResult?.real" class="inspector-section"><h3>真实伤害乘区</h3><div v-for="(value,key) in selectedResult.real.parts" :key="key" class="field-line"><span>{{ realPartsLabels[key] }}</span><strong>{{ num(value) }}</strong></div><p v-for="message in selectedResult.real.diagnostics" :key="message" class="muted">{{ message }}</p></div><div class="inspector-section"><h3>候选效果与来源</h3><div v-for="source in selectedResult?.formula.effects" :key="`${source.definition}/${source.effect}/${source.action}`" class="source-pill"><strong>{{ definitionLabel(project, source.definition) }} / {{ effectLabel(project, source.definition, source.effect) }}</strong></div><p v-if="!selectedResult?.formula.effects.length" class="muted">此记录没有读取候选区间效果。</p><details><summary>技术详情：查看节点来源</summary><code v-for="source in selectedResult?.sources" :key="source.path" class="source-path">{{ source.path }}</code></details></div><button class="secondary" @click="removeRecord(selected.id)">删除所选记录</button></template><p v-else class="muted">选择一条记录查看明细。</p></aside>
      </div>

      <div v-else-if="page === 'team'" class="team-layout"><section class="panel"><RealGamePanel mode="axis" /><AxisCreation /><div class="shell-effect-group"><h3>轴内条件</h3><label>新条件名称<input v-model="newCondition" aria-label="新条件名称" maxlength="160"></label><button @click="addCondition">添加条件</button><label v-for="key in conditionKeys" :key="key">条件 {{ inputLabel(key) }}<select :aria-label="`轴内条件 ${inputLabel(key)}`" :value="conditionValue(key)" @change="setCondition(key, $event)"><option value="unknown">待确认（未知）</option><option value="true">明确满足</option><option value="false">明确不满足</option></select></label></div><div class="panel-heading"><div><h2>当前轴队伍</h2><p>编辑候选属性及效果，不覆盖账号实际装备。</p></div><span class="subtle-tag">{{ project.candidate.actors.length }} 位角色</span></div><label>当前轴角色<select v-model="actorId"><option v-for="owner in project.candidate.actors" :key="owner.id" :value="owner.id">{{ actorLabel(project, owner.id) }} / {{ definitionLabel(project, owner.character) }}</option></select></label><template v-if="actor"><button @click="removeActor">移除当前队员及其记录</button><details v-if="actor.accountSnapshot"><summary>技术详情：账号与实物来源快照</summary><p>{{ actor.accountSnapshot.accountId }} / {{ actor.accountSnapshot.characterId }}</p><p v-for="item in actor.accountSnapshot.artifacts" :key="item.id">{{ item.name }} · {{ item.id }}</p></details><div class="team-role-card"><span class="large-avatar">轴</span><div><h3>{{ actorLabel(project, actor.id) }}</h3><p>{{ definitionLabel(project, actor.character) }}</p></div><span class="snapshot-tag">项目快照</span></div><div v-if="!actor.realBuild" class="candidate-form"><label>候选武器<select v-model="actor.weapon"><option v-for="d in project.definitions" :key="d.id" :value="d.id">{{ definitionLabel(project, d.id) }}</option></select></label><label v-for="(quantity, key) in actor.inputs" :key="key">{{ key === 'attack' ? '候选攻击力' : `候选 ${key}` }}<input :aria-label="key === 'attack' ? '候选攻击力' : `候选 ${key}`" type="number" step="any" :value="quantity.value" @input="quantity.value = number($event)"><small>{{ unitLabel(quantity.unit) }}</small></label></div><div v-for="definition in equipmentDefinitions" v-show="!actor.realBuild" :key="definition.id" class="shell-effect-group"><h3>{{ definitionLabel(project, definition.id) }} · 效果</h3><p v-if="!definition.effects.length" class="muted">此定义没有区间效果。</p><div v-for="effect in definition.effects" :key="effect.id" class="shell-effect-editor"><strong>{{ effectLabel(project, definition.id, effect.id) }}</strong><div class="candidate-form"><label>生效起点（毫秒）<input type="number" min="0" :value="effect.startMs" @input="effect.startMs = number($event)"></label><label>失效终点（毫秒）<input type="number" min="0" :value="effect.endMs" @input="effect.endMs = number($event)"></label><template v-for="node in definition.nodes.filter(n => n.id === effect.value)" :key="node.id"><label v-if="node.op === 'constant' && node.quantity.unit === 'scalar'">伤害加成（%）<input type="number" step="any" :value="node.quantity.value * 100" @input="node.quantity.value = number($event) / 100"></label></template></div><label class="checkbox-line"><input type="checkbox" :checked="Boolean(effect.condition)" @change="toggleCondition(effect, $event)">此效果需要额外触发条件</label><label v-if="effect.condition">条件 {{ inputLabel(effect.condition) }}<select :value="conditionValue(effect.condition)" @change="setCondition(effect.condition!, $event)"><option value="unknown">待确认（未知）</option><option value="true">明确满足</option><option value="false">明确不满足</option></select></label></div></div></template><p v-else class="design-callout">当前轴没有角色。请在上方创建合成角色，或从定义库与账号准备队伍。</p></section><aside class="panel team-result"><span class="section-eyebrow">候选计算结果</span><h2>当前方案</h2><div class="inspector-damage">{{ num(result.totalValue) }}<small>全轴伤害</small></div><div class="field-line"><span>目标值</span><strong>{{ num(result.objectiveValue) }}</strong></div><button class="primary" @click="navigate('timeline')">查看时间轴 →</button><p class="muted">{{ actor?.realBuild ? 