; font-size: 10px; font-weight: 500; }.track-label small { color: #a4ad98; display: block; font-size: 8px; margin-top: 7px; }.track-dot { width: 5px; height: 5px; border-radius: 50%; background: #8ea580; display: inline-block; flex-shrink: 0; }.track-label > .track-dot { position: absolute; left: 10px; top: 21px; }.track-dot.green { background: #64865b; }.track-dot.gold { background: #c6a466; }.track-dot.slate { background: #9aa9ab; }.track-dot.pale { background: #c5cbbd; }.track-content { position: relative; min-width: 0; }.track-grid { position: absolute; inset: 0; background: repeating-linear-gradient(to right, #e9eee4 0, #e9eee4 1px, transparent 1px, transparent 12.5%); pointer-events: none; }.empty-track, .future-track-note { position: absolute; left: 20px; top: 37px; color: #bac2ae; font-size: 9px; }.damage-track { min-height: 118px; }.track-row.faded { opacity: .35; }.workspace-design .hit-marker { position: absolute; top: 21px; transform: translateX(-50%); width: 88px; height: 76px; padding: 0; border: 0; background: transparent; border-radius: 0; color: #6d8c5b; }.workspace-design .hit-marker:hover { background: transparent; border: 0; }.marker-card { border: 1px solid #dbe6d1; background: #f2f7eb; padding: 9px 10px; border-radius: 6px; display: grid; text-align: left; gap: 5px; position: relative; z-index: 2; }.marker-card small { color: #99aa88; font-size: 8px; white-space: nowrap; }.marker-card strong { font-size: 17px; font-weight: 600; }.chosen .marker-card { background: #e5efdb; border-color: #87a976; box-shadow: 0 0 0 2px #dfead640; }.marker-stem { position: absolute; width: 1px; background: #a8bf92; top: -20px; bottom: -12px; left: 50%; }.marker-diamond { position: absolute; width: 7px; height: 7px; bottom: -4px; left: calc(50% - 3px); transform: rotate(45deg); background: #7ca264; border: 2px solid #e7efde; z-index: 2; }.effect-bar { position: absolute; top: 27px; left: 0; width: 62.5%; border: 1px solid #eadbb6; background: #f8f0dc; color: #aa9056; border-radius: 0 5px 5px 0; height: 32px; display: flex; align-items: center; justify-content: space-between; padding: 0 9px; font-size: 9px; white-space: nowrap; }.effect-bar small { font-size: 8px; color: #baa575; }.future-track { min-height: 83px; background: #fcfdfb; }.future-track .track-label strong { color: #a4ac98; }.future-track-note { top: 32px; }.timeline-footer { border-top: 1px solid #e9eee4; display: flex; gap: 16px; align-items: center; flex-wrap: wrap; padding: 15px 21px; color: #a2ac93; font-size: 8px; }.timeline-footer > span { display: flex; gap: 6px; align-items: center; }.timeline-footer > p { margin-left: auto; color: #b0b9a2; font-size: 8px; }.legend-diamond { width: 5px; height: 5px; transform: rotate(45deg); background: #89a875; display: inline-block; }.legend-bar { width: 12px; height: 5px; background: #e8d7a8; border-radius: 2px; }.axis-summary { display: flex; align-items: center; gap: 35px; padding: 20px 24px; background: #f7faf2; border-top: 1px solid #e3ebd8; }.axis-summary > div { display: grid; gap: 7px; }.axis-summary small { font-size: 9px; color: #96a184; }.axis-summary strong { font-size: 25px; letter-spacing: -.8px; color: #4d7140; font-weight: 600; }.axis-summary > div:nth-child(2) strong { color: #8d9f7d; font-size: 21px; }.axis-summary .summary-state { display: block; margin-left: auto; font-size: 9px; color: #94a382; }.status-dot { display: inline-block; width: 5px; height: 5px; background: #8cac70; border-radius: 50%; margin-right: 5px; }.summary-state button { display: block; margin-top: 7px; margin-left: 8px; }
.record-inspector { padding: 22px !important; }.inspector-title { display: flex; align-items: center; justify-content: space-between; gap: 10px; margin-bottom: 21px; }.inspector-title .section-eyebrow { font-size: 8px; letter-spacing: 1.1px; }.record-inspector h2 { font-size: 17px; margin-bottom: 7px; }.record-inspector > .monospace { font-size: 9px; }.inspector-damage { font-size: 33px; letter-spacing: -1px; font-weight: 600; color: #466b38; margin: 27px 0; }.inspector-damage small { display: block; font-weight: 400; font-size: 9px; color: #a2ac95; letter-spacing: 0; margin-top: 8px; }.inspector-fields { border-top: 1px solid #edf0e7; padding-top: 18px; }.inspector-fields label { color: #929e85; font-size: 10px; }.inspector-fields input[type=number] { color: #5e7850; background: #fcfdf9; font-size: 11px; }.field-line { display: flex; gap: 10px; justify-content: space-between; align-items: center; margin: 17px 0; font-size: 10px; }.field-line > span { color: #a2ac95; }.field-line strong, .field-line code { color: #75896a; font-size: 10px; font-weight: 400; }.workspace-design .checkbox-line { display: flex; align-items: center; gap: 8px; padding-top: 4px; font-size: 9px; }.checkbox-line input { width: 13px; height: 13px; accent-color: #70945a; padding: 0; }.inspector-section { border-top: 1px solid #edf0e7; margin-top: 22px; padding-top: 20px; }.inspector-section h3 { font-size: 11px; color: #849575; margin-bottom: 13px; }.inspector-section h3 > span { color: #afbaa0; font-size: 9px; margin-left: 7px; }.formula-box { padding: 13px 12px; border-radius: 5px; background: #f4f7ef; display: grid; gap: 10px; color: #8d9d7b; }.formula-box > span { font-size: 8px; }.formula-box > strong { font-family: 'Cascadia Code', Consolas, monospace; font-size: 12px; font-weight: 500; color: #6f885b; }.inspector-section > .muted { margin-top: 10px; font-size: 8px; }.source-pill { display: flex; align-items: center; gap: 9px; padding: 12px 10px; background: #fcf9f0; border: 1px solid #eee6cf; border-radius: 5px; }.source-pill div { display: grid; gap: 5px; }.source-pill strong { font-size: 9px; color: #a58d57; font-weight: 500; }.source-pill small { font-size: 8px; color: #b5a57e; }.record-inspector details { margin-top: 17px; }.record-inspector summary { color: #a1ac91; font-size: 9px; cursor: pointer; }.source-path { display: block; font-size: 8px; line-height: 1.8; color: #9caa8c; margin-top: 7px; overflow-wrap: anywhere; }
.library-layout, .team-layout, .analysis-layout { display: grid; grid-template-columns: 230px minmax(0,1fr); gap: 20px; margin: 0 30px; align-items: start; }.workspace-design .roster { padding: 20px 14px; }.roster > .panel-heading { padding: 0 6px; }.library-note { margin: 16px 6px 20px !important; color: #9aa68e; font-size: 10px; }.workspace-design .roster-item { display: flex; align-items: center; gap: 10px; width: 100%; margin: 7px 0; padding: 12px 10px; border-color: transparent; background: transparent; text-align: left; }.workspace-design .roster-item.selected { background: #eff5e9; border-color: #dde8d2; }.role-avatar { height: 34px; width: 34px; background: #e8efdf; color: #8b9e74; display: grid; place-content: center; border-radius: 7px; }.roster-item > span:nth-child(2) { display: grid; gap: 7px; }.roster-item strong { font-size: 11px; font-weight: 500; }.roster-item small { font-size: 8px; color: #a3ad96; }.chevron { margin-left: auto; color: #b4bdab; font-size: 18px; }.role-hero { display: flex; gap: 18px; align-items: center; margin: 8px 0 27px; }.large-avatar { width: 64px; height: 64px; border-radius: 12px; background: linear-gradient(135deg,#eef3e5,#dde8cf); display: grid; place-content: center; color: #91a779; font-size: 25px; flex-shrink: 0; }.role-hero h2 { margin: 8px 0; font-size: 21px; }.role-hero p { color: #a0ab93; font-size: 10px; }.role-hero > .subtle-tag { margin-left: auto; }.detail-tabs { display: flex; gap: 25px; border-bottom: 1px solid #e8eddf; margin-bottom: 22px; color: #a5ae98; font-size: 11px; }.detail-tabs > span { padding: 0 0 13px; }.detail-tabs > .active { color: #668254; border-bottom: 2px solid #7c9d62; }.design-callout { padding: 17px 20px; border: 1px solid #e5eadc; background: #f8faf4; border-radius: 6px; color: #98a288; margin-top: 20px; }.design-callout strong { font-size: 11px; font-weight: 500; color: #7c9169; }.design-callout p { font-size: 10px; line-height: 1.9; margin-top: 8px; }.equipment-heading { display: flex; justify-content: space-between; align-items: center; gap: 10px; margin: 28px 0 18px; }.equipment-heading small { font-size: 9px; color: #a6af9b; }.equipment-slots { display: grid; grid-template-columns: repeat(6,minmax(0,1fr)); gap: 10px; }.equipment-slots > div { border: 1px solid #e8ecdf; border-radius: 6px; padding: 19px 7px; text-align: center; display: grid; gap: 10px; }.equipment-slots > div > span { font-size: 29px; color: #b2bd9c; }.equipment-slots strong { font-size: 10px; font-weight: 500; }.equipment-slots small { color: #b3bba7; font-size: 8px; }.independent-note { display: flex; gap: 12px; color: #a1ad91; font-size: 10px; line-height: 1.9; padding: 25px 0 3px; }.independent-note > span { font-size: 21px; color: #bcc7ad; }
.workspace-design .artifact-library, .workspace-design .definition-library, .workspace-design .settings-page { margin: 0 30px; }.inventory-toolbar { display: flex; align-items: end; gap: 20px; padding: 23px 0; border-bottom: 1px solid #e9eddf; margin-bottom: 23px; }.inventory-toolbar label { font-size: 10px; color: #94a085; width: 150px; }.inventory-toolbar select { font-size: 11px; }.inventory-summary { font-size: 10px; color: #a3ad95; padding-bottom: 10px; }.inventory-summary span { margin: 0 7px; }.inventory-toolbar > button { margin-left: auto; }.artifact-grid { display: grid; grid-template-columns: repeat(5,minmax(0,1fr)); gap: 15px; }.artifact-card { border: 1px solid #e6eadd; border-radius: 7px; padding: 15px; }.artifact-top { display: flex; align-items: center; justify-content: space-between; font-size: 9px; color: #9aa68b; gap: 5px; }.artifact-top small { font-size: 7px; color: #bec5b2; }.artifact-art { height: 106px; display: grid; place-content: center; color: #b6aa7b; font-size: 63px; background: radial-gradient(ellipse,#f5f1e1,transparent 70%); }.artifact-card h3 { font-size: 11px; color: #7e886c; }.artifact-card > p { font-size: 8px; color: #acb39e; margin-top: 10px; }.artifact-lines { display: grid; gap: 8px; padding: 18px 0; }.artifact-lines > span { height: 5px; width: 78%; background: #f0f3e9; border-radius: 4px; }.artifact-lines > span:nth-child(2) { width: 57%; }.artifact-lines > span:nth-child(3) { width: 67%; }.artifact-card footer { padding-top: 14px; border-top: 1px solid #edf0e6; display: grid; gap: 7px; font-size: 9px; color: #98a185; }.artifact-card footer code { font-size: 7px; color: #bcc4ad; }
.project-library { margin: 0 30px; }.library-heading { display: flex; align-items: center; justify-content: space-between; margin: 5px 0 20px; }.project-card-grid { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 20px; max-width: 850px; }.workspace-design .axis-project-card { padding: 23px; text-align: left; min-height: 250px; }.project-card-top { display: flex; justify-content: space-between; align-items: center; color: #b1bca3; }.mini-axis { height: 62px; position: relative; margin: 12px 0 17px; }.mini-axis > span { height: 2px; position: absolute; left: 0; right: 0; top: 31px; background: #e4ecd9; }.mini-axis > i { position: absolute; top: 26px; left: 25%; width: 12px; height: 12px; transform: rotate(45deg); background: #a4be8e; border: 3px solid #f1f6e9; z-index: 1; }.mini-axis > i:nth-child(2) { left: 75%; }.axis-project-card h3 { font-size: 16px; color: #627d50; }.axis-project-card > p { color: #a6b097; font-size: 10px; line-height: 1.9; margin-top: 10px; }.project-card-bottom { margin-top: 23px; padding-top: 17px; border-top: 1px solid #edf0e7; display: flex; justify-content: space-between; align-items: center; font-size: 9px; color: #a8b19a; }.project-card-bottom strong { color: #7b9665; font-size: 18px; }.empty-project { display: flex; flex-direction: column; align-items: center; justify-content: center; background: transparent !important; border-style: dashed !important; text-align: center !important; }.empty-project > span { color: #b8c3a6; font-size: 25px; margin-bottom: 18px; }.empty-project h3 { font-size: 13px; color: #9ba98b; }.empty-project > p { font-size: 10px; max-width: 225px; }
.team-layout { grid-template-columns: minmax(0,1fr) 285px; }.team-role-card { display: flex; gap: 15px; align-items: center; margin: 26px 0; padding-bottom: 25px; border-bottom: 1px solid #edf0e7; }.team-role-card p { color: #a4ae96; font-size: 10px; margin-top: 8px; }.team-role-card > .snapshot-tag { margin-left: auto; }.candidate-form { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 20px; }.candidate-form label { font-size: 11px; color: #91a181; }.candidate-form input, .candidate-form select { font-size: 12px; padding: 11px 12px; background: #fdfefb; }.actual-calculation { margin-top: 28px; }.team-result h2 { margin-top: 12px; }.team-result > button { width: 100%; margin: 15px 0; }.team-result > .muted { font-size: 9px; }.analysis-layout { grid-template-columns: minmax(0,1fr) 285px; }.analysis-stats { display: grid; grid-template-columns: repeat(3,1fr); padding: 30px 0; margin: 20px 0 25px; border-top: 1px solid #edf0e7; border-bottom: 1px solid #edf0e7; }.analysis-stats > div { display: grid; gap: 11px; padding-left: 25px; border-left: 1px solid #edf0e7; }.analysis-stats > div:first-child { padding-left: 0; border: 0; }.analysis-stats > div > small { font-size: 10px; color: #9cab8b; }.analysis-stats strong { color: #5d814a; font-size: 30px; font-weight: 600; letter-spacing: -.7px; }.analysis-stats strong small { font-size: 10px; color: #acb79b; margin-left: 5px; }.chart-title { display: flex; justify-content: space-between; gap: 10px; color: #7d926b; }.chart-title > span { color: #acb79b; font-size: 9px; font-weight: 400; }.contribution-chart { margin: 25px 0; }.workspace-design .contribution-chart button { display: flex; align-items: center; gap: 18px; width: 100%; padding: 18px 0; border: 0; border-bottom: 1px solid #f0f3e9; background: transparent; text-align: left; }.contribution-chart button > span:first-child { font-size: 11px; width: 75px; color: #91a27e; flex-shrink: 0; }.contribution-chart small { display: block; margin-top: 7px; font-size: 8px; color: #b2bca3; }.contribution-track { flex: 1; height: 16px; border-radius: 3px; background: #f5f8ef; overflow: hidden; }.contribution-track i { height: 100%; display: block; background: #a8c193; border-radius: 3px; }.contribution-chart strong { font-size: 14px; color: #7b9766; width: 52px; text-align: right; }.chart-arrow { color: #b5c0a6; font-size: 13px; }.analysis-footnote { font-size: 9px; color: #aeb89f; line-height: 1.8; }.analysis-layout aside h2 { margin: 13px 0 16px; }.analysis-flow { padding: 25px 0; }.analysis-flow > div { display: flex; gap: 12px; align-items: center; padding: 12px; border: 1px solid #eaf0e0; border-radius: 6px; background: #f9fbf5; }.analysis-flow span { font-size: 9px; color: #b4c3a4; }.analysis-flow strong { font-size: 10px; color: #8d9f7c; font-weight: 500; }.analysis-flow > i { font-style: normal; display: block; text-align: center; color: #ccd5bf; margin: 9px 0; }
.definition-tabs { margin: 24px 0; }.definition-grid { display: grid; grid-template-columns: repeat(3,minmax(0,1fr)); gap: 18px; }.definition-tile { border: 1px solid #e5ebdc; border-radius: 7px; padding: 20px; }.definition-tile > div { display: flex; justify-content: space-between; align-items: center; margin-bottom: 23px; }.definition-symbol { font-size: 23px; color: #9eaf89; width: 40px; height: 40px; background: #f0f5e7; border-radius: 8px; display: grid; place-content: center; }.definition-tile h3 { font-family: 'Cascadia Code', Consolas, monospace; font-size: 12px; color: #7c9568; overflow-wrap: anywhere; }.definition-tile p { font-size: 10px; color: #a7b296; margin-top: 11px; }.definition-tile footer { display: flex; justify-content: space-between; font-size: 8px; gap: 10px; color: #b2bea1; border-top: 1px solid #edf1e5; padding-top: 17px; margin-top: 25px; }.definition-empty { color: #a6b294; font-size: 11px; padding: 20px; }.settings-page > h2 { font-size: 21px; margin: 18px 0; }.settings-page > p { font-size: 12px; color: #99a68b; line-height: 2; max-width: 650px; }.settings-grid { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 25px; margin: 30px 0; }.settings-grid > div { background: #f8faf4; border: 1px solid #e8eddf; padding: 23px; border-radius: 7px; }.settings-grid h3 { margin-bottom: 13px; color: #80976b; }.settings-grid p { font-size: 11px; color: #a2ae92; line-height: 2; }.existing-link { font-size: 11px; }
.design-statusbar { display: flex; align-items: center; justify-content: space-between; gap: 15px; padding: 28px 30px 20px; color: #b1bba4; font-size: 8px; }.design-statusbar > span:first-child { display: flex; gap: 7px; align-items: center; }.statusbar-separator { margin: 0 8px; color: #c5ceba; }.mobile-menu, .drawer-shade { display: none; }.workspace-design.compact { grid-template-columns: 76px minmax(0,1fr); }.compact .design-sidebar { width: 76px; padding-inline: 10px; }.compact .brand { padding: 0; gap: 2px; }.compact .brand-symbol { width: 32px; flex-shrink: 0; }.compact .brand-copy, .compact .account-picker, .compact .nav-group > p, .compact .nav-group > button > span, .compact .sidebar-version, .compact .sidebar-bottom > button > span:last-child { display: none; }.compact .brand .collapse-button { margin-left: 0; padding-left: 3px; }.compact .nav-groups { margin-top: 35px; }.compact .nav-group > button { justify-content: center; padding: 13px 8px; }.compact .sidebar-bottom { padding-inline: 0; }.compact .sidebar-bottom > button { justify-content: center; }
